  "id": 42,
  "knowledge": "High-Pressure Data Flow",
  "description": "Highlights data flows under strain from data subject requests and bandwidth saturation.",
  "definition": "A data flow where DSRP > 50 and BSI > 50"
}

{
  "id": 1,
  "knowledge": "Bandwidth Saturation Index (BSI)",
  "description": "Quantifies how close a data flow is to saturating available bandwidth.",
  "definition": "BSI = \\text{BwidthPct} \\times \\frac{\\text{DataSizeMB}}{\\text{DurMin}}"
}

{
  "id": 34,
  "knowledge": "Data Subject Request Pressure (DSRP)",
  "description": "Quantifies pressure from data subject requests relative to response time.",
  "definition": "DSRP = \\text{DSRL} \\times \\text{RespTimeDay}"
}

{
  "id": 8,
  "knowledge": "Data Subject Request Load (DSRL)",
  "description": "Measures the workload from data subject requests.",
  "definition": "DSRL = \\text{AccReqNum} + \\text{DelReqNum} + \\text{RectReqNum} + \\text{PortReqNum}"
}

{
  "id": 30,
  "knowledge": "Data Flow Reliability Score (DFRS)",
  "description": "Quantifies the reliability of a data flow based on success rate and retry attempts.",
  "definition": "DFRS = \\text{DTE} \\times (1 - \\text{RtryTally} / (\\text{ErrTally} + 1))"
}

{
  "id": 48,
  "knowledge": "Incident Resolution Efficiency (IRE)",
  "description": "Measures how efficiently incidents are resolved relative to SLA compliance.",
  "definition": "IRE = \\text{SLApct} / (\\text{AvgResolHrs} + 1), \\text{where SLApct and AvgResolHrs are from RiskManagement, adding 1 to avoid division by zero.}"
}

{
  "id": 50,
  "knowledge": "Data Flow Stability Index (DFSI)",
  "description": "Quantifies the stability of data flows by balancing reliability and error recovery.",
  "definition": "DFSI = \\text{DFRS} \\times \\frac{\\text{SuccessPct}}{\\text{ErrTally} + 1}"
}

{
  "id": 37,
  "knowledge": "Bandwidth Risk Factor (BRF)",
  "description": "Evaluates risk from bandwidth overuse in sensitive data flows.",
  "definition": "BRF = \\text{BSI} \\times \\text{DSI}"
}

{
